using System.Globalization;using System.Text;using System.Text.Json;using GestionTubos.Domain.Enums;using GestionTubos.Infrastructure.Data;using GestionTubos.Infrastructure.Services;using GestionTubos.Shared.Tubos;using Microsoft.EntityFrameworkCore;
namespace GestionTubos.Api.Services;
// Corrección de soporte con especificación privada y respaldo. No expone un endpoint.
public static class RegularizarTubosClientes
{
 public sealed record Item(string Codigo,int ClienteId,string NombreLibreEsperado,DateTime FechaAltaUtcEsperada);
 public sealed record Resultado(string Codigo,int ClienteId,string Cliente,string RemitoIngreso);
 public static async Task EjecutarAsync(WebApplication app){var carpeta=Path.Combine(app.Environment.ContentRootPath,"App_Data","regularizar-clientes-20261027");if(!File.Exists(Path.Combine(carpeta,"run.flag"))||File.Exists(Path.Combine(carpeta,"status.json")))return;try{var items=JsonSerializer.Deserialize<List<Item>>(await File.ReadAllTextAsync(Path.Combine(carpeta,"solicitud.json")),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??[];using var scope=app.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<GestionTubosDbContext>();var resultado=await CorregirAsync(db,items,carpeta);await File.WriteAllTextAsync(Path.Combine(carpeta,"status.json"),JsonSerializer.Serialize(new{estado="Completado",resultado,fechaUtc=DateTime.UtcNow}));File.Move(Path.Combine(carpeta,"run.flag"),Path.Combine(carpeta,"completed.flag"),true);}catch(Exception e){await File.WriteAllTextAsync(Path.Combine(carpeta,"error.json"),JsonSerializer.Serialize(new{error=e.GetType().Name,mensaje=e.Message}));app.Logger.LogError(e,"No se completó la regularización de tubos de clientes");}}
 private static string Normalizar(string x)=>string.Concat(x.Normalize(NormalizationForm.FormD).Where(c=>CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark).Select(c=>char.IsLetterOrDigit(c)?char.ToLowerInvariant(c):' ')).Split(' ',StringSplitOptions.RemoveEmptyEntries).Aggregate("",(a,b)=>a.Length==0?b:a+" "+b);
 public static async Task<List<Resultado>> CorregirAsync(GestionTubosDbContext db,IReadOnlyList<Item>items,string carpeta)
 {
  if(items.Count!=3||items.Select(x=>x.Codigo).Distinct().Count()!=3||items.Select(x=>x.ClienteId).Distinct().Count()!=3)throw new InvalidOperationException("La solicitud debe identificar tres tubos y tres propietarios distintos.");
  await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var codigos=items.Select(x=>x.Codigo).ToArray();var tubos=await db.Tubos.Include(x=>x.Ubicacion).Where(x=>codigos.Contains(x.CodigoInterno)).ToListAsync();if(tubos.Count!=3)throw new InvalidOperationException("Los códigos ya no coinciden con la solicitud.");var clienteIds=items.Select(i=>i.ClienteId).ToArray();var clientes=await db.Clientes.Where(x=>clienteIds.Contains(x.Id)).ToDictionaryAsync(x=>x.Id);
  foreach(var i in items){var t=tubos.Single(x=>x.CodigoInterno==i.Codigo);if(!clientes.TryGetValue(i.ClienteId,out var c)||t.TipoPropietario!=TipoPropietarioTubo.OtroTercero||t.ClientePropietarioId!=null||t.NombrePropietarioExterno!=i.NombreLibreEsperado||t.FechaAltaUtc!=i.FechaAltaUtcEsperada||t.EstadoDisponibilidad!=EstadoDisponibilidad.Disponible||t.EstadoContenido!=EstadoContenido.Vacio||!t.Ubicacion.EsInterna||t.Ubicacion.GasBateria!=null)throw new InvalidOperationException("El tubo cambió desde la revisión; no se modificó ningún registro.");var nombres=new[]{c.RazonSocial,c.NombreComercial,$"{c.Apellido} {c.Nombre}",$"{c.Nombre} {c.Apellido}"}.Where(n=>!string.IsNullOrWhiteSpace(n)).Select(n=>Normalizar(n!));if(!nombres.Contains(Normalizar(i.NombreLibreEsperado)))throw new InvalidOperationException("El nombre registrado no coincide exactamente con la ficha del propietario.");if(await db.IngresosClientesDetalle.AnyAsync(d=>d.TuboId==t.Id&&d.FechaRetiroUtc==null)||await db.OperacionesCilindro.AnyAsync(o=>o.TuboId==t.Id&&o.FechaDevolucionUtc==null))throw new InvalidOperationException("El tubo ya tiene una operación activa.");}
  Directory.CreateDirectory(carpeta);await using(var file=new FileStream(Path.Combine(carpeta,"respaldo.json"),FileMode.CreateNew)){await JsonSerializer.SerializeAsync(file,new{fechaUtc=DateTime.UtcNow,items,tubos=tubos.Select(t=>db.Entry(t).Properties.ToDictionary(p=>p.Metadata.Name,p=>p.CurrentValue))});}
  var resultado=new List<Resultado>();foreach(var i in items){var t=tubos.Single(x=>x.CodigoInterno==i.Codigo);var anterior=t.NombrePropietarioExterno;var dto=new TuboGuardarDto{CodigoInterno=t.CodigoInterno,NumeroSerie=t.NumeroSerie,IdentificacionGrabada=t.IdentificacionGrabada,TipoGasId=t.TipoGasId,CapacidadTuboId=t.CapacidadTuboId,Marca=t.Marca,Fabricante=t.Fabricante,FechaFabricacion=t.FechaFabricacion,TipoPropietario=2,ClientePropietarioId=i.ClienteId,EstadoFisico=(int)t.EstadoFisico,EstadoContenido=(int)t.EstadoContenido,EstadoDisponibilidad=(int)t.EstadoDisponibilidad,UbicacionId=t.UbicacionId,Observaciones=t.Observaciones,RegistrarPruebaInicial=false};await new TuboService(db).ActualizarAsync(t.Id,dto,default);db.MovimientosCilindro.Add(new(){TuboId=t.Id,Tipo="Vinculación de propietario",ClienteId=i.ClienteId,UbicacionOrigenId=t.UbicacionId,UbicacionDestinoId=t.UbicacionId,EstadoAnterior="Otro propietario: "+anterior,EstadoPosterior="Cliente propietario #"+i.ClienteId,UsuarioResponsable="Soporte autorizado",Observaciones="Corrección solicitada por el usuario. Coincidencia exacta con la ficha del cliente; ubicación y contenido conservados."});await db.SaveChangesAsync();var r=await new IngresoClienteService(db).Recibir(new(){ClienteId=i.ClienteId,TuboIds=[t.Id],UbicacionId=t.UbicacionId,PersonaEntrega="No informada - regularización de ingreso",Observaciones=$"Regularización solicitada por el usuario de un tubo ya registrado vacío en planta el {t.FechaAltaUtc:yyyy-MM-dd}. No representa una nueva entrega física."},"Soporte autorizado",default);resultado.Add(new(t.CodigoInterno,i.ClienteId,r.Cliente,r.Numero));}
  await tx.CommitAsync();return resultado;
 }
}
